public class InnerHarnessHarnessTruncationStrategyConfigurationFactory(Action<Humidifier.BedrockAgentCore.HarnessTypes.HarnessTruncationStrategyConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.BedrockAgentCore.HarnessTypes.HarnessTruncationStrategyConfiguration>
{

    internal InnerHarnessHarnessSlidingWindowConfigurationFactory SlidingWindowFactory { get; set; }

    internal InnerHarnessHarnessSummarizationConfigurationFactory SummarizationFactory { get; set; }

    protected override Humidifier.BedrockAgentCore.HarnessTypes.HarnessTruncationStrategyConfiguration Create()
    {
        var harnessTruncationStrategyConfigurationResult = CreateHarnessTruncationStrategyConfiguration();
        factoryAction?.Invoke(harnessTruncationStrategyConfigurationResult);

        return harnessTruncationStrategyConfigurationResult;
    }

    private Humidifier.BedrockAgentCore.HarnessTypes.HarnessTruncationStrategyConfiguration CreateHarnessTruncationStrategyConfiguration()
    {
        var harnessTruncationStrategyConfigurationResult = new Humidifier.BedrockAgentCore.HarnessTypes.HarnessTruncationStrategyConfiguration();

        return harnessTruncationStrategyConfigurationResult;
    }
    public override void CreateChildren(Humidifier.BedrockAgentCore.HarnessTypes.HarnessTruncationStrategyConfiguration result)
    {
        base.CreateChildren(result);

        result.SlidingWindow ??= SlidingWindowFactory?.Build();
        result.Summarization ??= SummarizationFactory?.Build();
    }

} // End Of Class

